		} else {
			_ = db.PutSetting(ctx, mcpOAuthSettingKey, mcpOAuthSettings{}, nil, operator.ID)
		}
	})
	if err := db.PutSetting(ctx, mcpOAuthSettingKey, settings, nil, operator.ID); err != nil {
		t.Fatal(err)
	}
	return handler, db, provider
}

